<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$pageTitle='Laporan Saya';$uid=(int)currentUser()['id_user'];$s=$koneksi->prepare('SELECT l.*,k.nama_kategori,lo.nama_lokasi FROM laporan l JOIN kategori k ON k.id_kategori=l.id_kategori JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi WHERE l.id_user=? ORDER BY l.created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();require __DIR__.'/../includes/header.php';?><div class="panel"><div class="panel-head"><div><h2>Semua laporan saya</h2><small class="muted">Pantau perkembangan setiap laporan.</small></div><a class="btn" href="lapor.php">+ Buat laporan</a></div><div class="table-wrap"><table><tr><th>Barang</th><th>Jenis</th><th>Lokasi</th><th>Tanggal</th><th>Status</th></tr><?php if(!$rows->num_rows):?><tr><td colspan="5"><div class="empty">Belum ada laporan.</div></td></tr><?php endif;while($r=$rows->fetch_assoc()):?><tr><td><div style="display:flex;align-items:center;gap:10px"><?php if(!empty($r['foto_barang'])): ?><img src="<?=e(url('uploads/barang/'.$r['foto_barang']))?>" alt="Foto <?=e($r['nama_barang'])?>" style="width:48px;height:48px;object-fit:cover;border-radius:12px;border:1px solid var(--line)"><?php endif; ?><div><b><?=e($r['nama_barang'])?></b><br><small class="muted"><?=e($r['nama_kategori'])?></small></div></div></td><td><?=e(ucfirst($r['jenis_laporan']))?></td><td><?=e($r['nama_lokasi'])?></td><td><?=e(date('d/m/Y',strtotime($r['tanggal_kejadian'])))?></td><td><span class="badge <?=e($r['status'])?>"><?=e(statusLabel($r['status']))?></span></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
